    # If the first occurrence plus n/2 is within the array bounds and 
    # the element at that position is x, then x is the majority element
    if first_occurrence != -1 and (first_occurrence + n // 2) < n and arr[first_occurrence + n // 2] == x:
        return True
    else:
        return False
